        },
        "required": [
          "path",
          "instrument"
        ],
        "additionalProperties": false
      }
    },
    {
      "name": "sample_set",
      "description": "Set sample metadata",
      "inputSchema": {
        "type": "object",
        "properties": {
          "instrument": {
            "type": "integer"
          },
          "sample": {
            "type": "integer"
          },
          "name": {
